const TEX_PCB = canvasTex(2048, 1024, (g, w, h) => {
  const r = mulberry32(21);
  g.fillStyle = '#161a18'; g.fillRect(0, 0, w, h);
  for (let i = 0; i < 520; i++) {
    let x = r() * w, y = r() * h;
    g.strokeStyle = r() < 0.85 ? 'rgba(52,62,56,0.55)' : 'rgba(120,92,52,0.35)';
    g.lineWidth = 1 + r() * 2.5;
    g.beginPath(); g.moveTo(x, y);
    for (let k = 0; k < 4; k++) {
      const horiz = r() < 0.5, len = 30 + r() * 220;
      if (r() < 0.3) { x += len * 0.7; y += (r() < 0.5 ? -1 : 1) * len * 0.7; }
      else if (horiz) x += (r() < 0.5 ? -1 : 1) * len; else y += (r() < 0.5 ? -1 : 1) * len;
      g.lineTo(x, y);
    }
    g.stroke();
  }
  for (let i = 0; i < 900; i++) {
    g.fillStyle = r() < 0.7 ? 'rgba(90,96,90,0.55)' : 'rgba(150,118,70,0.6)';
