  }
});

// Perforated sheet metal (server vents, backplate windows).
const TEX_PERF = canvasTex(256, 256, (g, w, h) => {
  g.fillStyle = '#9aa0a4'; g.fillRect(0, 0, w, h);
  g.fillStyle = '#0b0c0d';
  const s = 16;
  for (let j = 0; j < h / s + 1; j++) for (let i = 0; i < w / s + 1; i++) {
    const x = i * s + (j % 2) * s / 2, y = j * s * 0.866;
    g.beginPath(); g.arc(x, y, s * 0.3, 0, Math.PI * 2); g.fill();
  }
}, true, [1, 1]);

